using System;
using System.IO;
using System.Linq;
using System.Xml.Linq;
using System.Drawing;
using System.Drawing.Imaging;
namespace JingFamily {
 public static class DiagramTests {
  public static int Run(string dir){int count=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Diagram test: "+label);count++;};Store.Data=Store.Sample();string output=Path.Combine(dir,"diagram");Directory.CreateDirectory(output);using(var tree=new FamilyTree()){
   tree.Size=new Size(1100,700);tree.Relayout();var l=tree.LayoutData;check(l.Boxes.Count==7&&l.Layers==3,"seven cards three layers");var rects=l.Boxes.Values.ToArray();check(!rects.SelectMany((a,i)=>rects.Skip(i+1).Select(b=>a.IntersectsWith(b))).Any(x=>x),"cards do not overlap");check(l.Ranks[Store.Data.People[0].Id]==l.Ranks[Store.Data.People[1].Id],"spouses same layer");check(l.Ranks[Store.Data.People[2].Id]>l.Ranks[Store.Data.People[0].Id],"parent before child");
   string svg=Path.Combine(output,"世系图-玉笺.svg");tree.ExportSvg(svg);var doc=XDocument.Load(svg);XNamespace s="http://www.w3.org/2000/svg";check(doc.Root.Name==s+"svg","SVG namespace");check(doc.Descendants(s+"g").Count(x=>x.Attribute("data-person")!=null)==7,"one SVG group per member");check(!doc.Descendants(s+"image").Any(),"pure vector default");check(doc.Descendants(s+"polyline").Any(),"vector connections");check(!File.ReadAllText(svg).Contains("联系方式"),"contact information excluded");
   tree.ExportPng(Path.Combine(output,"世系图-玉笺.png"));tree.ExportPng(Path.Combine(output,"世系图-高清.png"),2,false);using(var image=Image.FromFile(Path.Combine(output,"世系图-高清.png")))check(image.Width==(int)Math.Ceiling(l.Size.Width*2),"2x PNG dimensions");tree.ExportEmf(Path.Combine(output,"世系图.emf"));using(var meta=new Metafile(Path.Combine(output,"世系图.emf")))check(meta.GetMetafileHeader().IsEmfOrEmfPlus(),"EMF format");tree.ExportHtml(Path.Combine(output,"世系图-交互.html"));string html=File.ReadAllText(Path.Combine(output,"世系图-交互.html"));check(html.Contains("onpointermove")&&html.Contains("getBBox")&&html.Contains("data-person"),"standalone interactive SVG HTML");check(!html.Contains("<script src="),"no external scripts");
   tree.Options.Theme=1;tree.ExportPng(Path.Combine(output,"世系图-黛青.png"));tree.ExportSvg(Path.Combine(output,"世系图-黛青.svg"));check(File.ReadAllText(Path.Combine(output,"世系图-黛青.svg")).Contains("#112629"),"dark theme");tree.Options.Theme=2;tree.ExportPng(Path.Combine(output,"世系图-墨印.png"));tree.ExportPng(Path.Combine(output,"世系图-透明.png"),1,true);using(var image=new Bitmap(Path.Combine(output,"世系图-透明.png"))){check(image.GetPixel(0,0).A==0,"transparent outside");var r=tree.LayoutData.Boxes.Values.First();check(image.GetPixel((int)r.X+22,(int)r.Y+84).A==255,"white card preserved on transparent export");}
   tree.Options.Compact=true;tree.ExportPng(Path.Combine(output,"世系图-紧凑.png"));check(tree.LayoutData.CardHeight==108,"compact geometry");tree.Options.Compact=false;tree.Options.Theme=0;tree.Mode="祖先";tree.FocusId=Store.Data.People[6].Id;tree.Options.IncludeSpouses=false;tree.Relayout();check(tree.LayoutData.People.Count==5,"ancestor filter");tree.Options.Depth=1;tree.Relayout();check(tree.LayoutData.People.Count==3,"ancestor depth");tree.Options.Depth=0;tree.Mode="后代";tree.FocusId=Store.Data.People[0].Id;tree.Relayout();check(tree.LayoutData.People.Count==5,"descendant filter");tree.Options.IncludeSpouses=true;tree.Relayout();check(tree.LayoutData.People.Count==7,"branch spouse option");tree.Mode="近亲";tree.FocusId=Store.Data.People[2].Id;tree.Options.IncludeSpouses=false;tree.Relayout();check(tree.LayoutData.People.Count==7,"immediate family filter");tree.Mode="全部成员";tree.SelectedId=Store.Data.People[0].Id;tree.ToggleBranch();check(tree.LayoutData.People.Count==3,"collapse descendants");tree.ExpandAll();check(tree.LayoutData.People.Count==7,"expand branches");check(tree.CenterPerson(Store.Data.People[6].Id),"locate member");tree.FitView();check(tree.ZoomValue>0&&tree.ZoomValue<=3,"fit view");check(tree.PrintPageCount(false,new Rectangle(0,0,700,500))==1&&tree.PrintPageCount(true,new Rectangle(0,0,700,500))>1,"print pagination");
   Store.Data.People[0].Name="景<明&远";tree.ExportSvg(Path.Combine(output,"escape.svg"));check(XDocument.Load(Path.Combine(output,"escape.svg")).Descendants(s+"g").Any(x=>(string)x.Attribute("data-person")=="景<明&远"),"SVG escaped names");Store.Data.People[0].Name="景明远";using(var image=new Bitmap(80,80)){using(var g=Graphics.FromImage(image))g.Clear(Color.DarkGreen);image.Save(Path.Combine(output,"avatar.png"));}Store.Data.People[0].Portrait=Store.AddMedia(Path.Combine(output,"avatar.png"));tree.Options.ShowPhotos=true;tree.ExportSvg(Path.Combine(output,"photo.svg"));check(XDocument.Load(Path.Combine(output,"photo.svg")).Descendants(s+"image").Count()==1,"embedded portrait");tree.Options.ShowPhotos=false;
   var pa=new Person{Name="甲"};var pb=new Person{Name="乙",FatherId=pa.Id};var pc=new Person{Name="丙"};var pd=new Person{Name="丁",FatherId=pc.Id};pa.Spouses.Add(pd.Id);pd.Spouses.Add(pa.Id);pb.Spouses.Add(pc.Id);pc.Spouses.Add(pb.Id);Store.Data=new FamilyData();Store.Data.People.AddRange(new[]{pa,pb,pc,pd});Store.Validate(Store.Data);tree.Options.Depth=0;tree.Relayout();check(tree.LayoutData.Notice!=""&&tree.LayoutData.Boxes.Count==4,"cross lineage fallback");rects=tree.LayoutData.Boxes.Values.ToArray();check(!rects.SelectMany((r,i)=>rects.Skip(i+1).Select(x=>r.IntersectsWith(x))).Any(x=>x),"fallback no overlap");
   Store.Data=Store.Sample();var partner=new Person{Name="另一配偶",Gender="女"};var father=Store.Data.People[2];father.Spouses.Add(partner.Id);partner.Spouses.Add(father.Id);Store.Data.People.Add(partner);Store.Data.People.Add(new Person{Name="另一分支子女",FatherId=father.Id,MotherId=partner.Id});Store.Validate(Store.Data);tree.Relayout();check(tree.LayoutData.Boxes.Count==9&&tree.LayoutData.Units.Any(u=>u.Members.Count==3),"multiple spouse family group");tree.ExportSvg(Path.Combine(output,"多配偶示例.svg"));Store.Data=Store.Sample();tree.SelectedId="";tree.Relayout();tree.ExportPng(Path.Combine(output,"世系图-玉笺.png"));tree.ExportSvg(Path.Combine(output,"世系图-玉笺.svg"));
  }
  using(var page=new DiagramPage("",id=>{})){page.Size=new Size(1120,730);page.CreateControl();page.PerformLayout();using(var b=new Bitmap(page.Width,page.Height)){page.DrawToBitmap(b,new Rectangle(0,0,b.Width,b.Height));b.Save(Path.Combine(output,"图谱界面预览.png"));}count++;}using(var settings=new DiagramSettings(new DiagramOptions())){settings.CreateControl();count++;}return count;
  }
 }
}
